/**  Streamed on the channel of `dashboard_watch` (HOST-14), each naming its host. */
export type DashboardEvent = 
/**
 *  Whether the host's first hop answered the HOST-10 probe: the host itself, or its
 *  outermost jump host.
 */
{ kind: "probe"; host_id: string; online: boolean } | 
/**  Waiting for one of the connection slots, or signing in. */
{ kind: "connecting"; host_id: string } | 
/**
 *  The host's connection settings changed since its readings were made, so they may be of
 *  another server: they are dropped.
 */
{ kind: "reset"; host_id: string } | 
/**  Connected and reading, over the dashboard's own connection or a tab's (`tab`). */
{ kind: "reading"; host_id: string; os: string | null; tab: boolean } | 
/**  A reading, one per interval. */
{ kind: "stats"; host_id: string; stats: ServerStatsView } | 
/**
 *  The server does not run Linux, so only its online status shows. `system` is its name,
 *  or empty when unknown.
 */
{ kind: "unsupported"; host_id: string; system: string } | 
/**
 *  The connection needs the user; the dashboard waits for **Retry**, a change to the host,
 *  or a tab on it. `error` is the server's answer, when there was one.
 */
{ kind: "held"; host_id: string; hold: DashboardHold; error: AppError | null } | 
/**  Connecting or reading failed; tried again after a minute. */
{ kind: "failed"; host_id: string; error: AppError };

/**  Why the dashboard does not sign in to a host on its own: the connection needs the user. */
export type DashboardHold = 
/**  The host or a jump host asks for its password on every connection (SSH-03). */
"password" | 
/**  The key's passphrase is not saved, or the saved one is wrong. */
"passphrase" | 
/**  The server wants keyboard-interactive answers, such as a verification code (SSH-08). */
"prompt" | 
/**  The server's host key is not trusted yet (SSH-04). */
"host_key_new" | 
/**  The server's host key differs from the trusted one (SSH-04). */
"host_key_changed" | 
/**  The server rejected the saved credentials. Not tried again until **Retry**. */
"sign_in_failed";

export type DashboardLayout = "cards" | "table";

export type Density = "regular" | "compact";

export type DeployDatabaseAction = "create" | 
/**  An existing database with nothing but Hatoba's migrations. */
"use" | 
/**  The database already bound to the Hatoba Worker. */
"bound";

export type DeployOutcome = {
	url: string,
	/**  `false`: the Worker has not answered yet (step 8 is waiting); `deploy_check` asks again. */
	ready: boolean,
};

/**  What step 2 found, shown before anything is written. */
export type DeployPlan = {
	/**  The account's workers.dev subdomain; `None` means the user has to choose one. */
	subdomain: string | null,
	worker: DeployWorkerAction,
	database: DeployDatabaseAction | null,
	database_name: string | null,
	/**
	 *  For `has_vault`: the workers.dev URL to join it on (Flow C), or `None` when no workers.dev
	 *  URL reaches the Worker.
	 */
	vault_url: string | null,
};

/**  Sent on the `deploy_run` channel as each step starts and ends. */
export type DeployProgress = {
	step: DeployStep,
	status: DeployStepStatus,
};

/**  Step 1 passed. Later calls name the deployment by `handle`; the API token stays in Rust. */
export type DeployStart = {
	handle: string,
	/**  The token belongs to the account given with it rather than to a user. */
	account_owned: boolean,
	/**  The accounts a user token reaches; empty when the user has to enter the account ID. */
	accounts: CloudflareAccount[],
	/**  The default Worker and database names. */
	worker_name: string,
	database_name: string,
};

export type DeployStep = "verify" | "inspect" | "create_database" | "migrate" | "upload" | "setup_token" | "route" | "wait";

export type DeployStepStatus = "running" | "done" | "skipped";

export type DeployTarget = {
	account_id: string,
	worker_name: string,
	database_name: string,
	/**  The workers.dev subdomain to create when the account has none. */
	subdomain: string | null,
};

export type DeployWorkerAction = "create" | "update" | 
/**  A Hatoba Worker whose database holds a vault: the deployment stops. */
"has_vault" | 
/**  A Worker the app does not recognize: the deployment stops. */
"foreign";

export type DeviceView = {
	device_id: string,
	name: string,
	platform: string,
	created_at: number,
	last_seen: number,
	current: boolean,
};

/**
 *  A text file dropped on the AI panel (AI-35), named by its base name only, never its path (a
 *  path can name the local user).
 */
export type DroppedFile = { status: "ok"; name: string; text: string } | { status: "refused"; name: string; reason: DroppedFileRefusal };

/**  Why a file dropped on the AI panel is not attached (AI-35): the panel's own reasons. */
export type DroppedFileRefusal = 
/**  An image, which attachments do not take yet. */
"image" | 
/**  Over 256 KB. */
"too_large" | 
/**  NUL bytes or invalid UTF-8. */
"binary" | 
/**  Not a file, gone, or not readable. */
"unreadable";

export type ErrorCode = "locked" | "not_initialized" | "already_initialized" | "wrong_password" | "wrong_recovery_code" | "throttled" | 
/**  SEC-11: `attempts_left` says how many more wrong PINs the PIN takes. */
"wrong_pin" | 
/**  SEC-11: no PIN unlock is possible now; the master password unlocks. */
"pin_unavailable" | 
/**
 *  SEC-10: Touch ID can't be used now (the lid is closed, too many failed fingers, no sensor).
 *  Only macOS produces it.
 */
"biometric_unavailable" | 
/**
 *  SEC-07, SEC-10: the saved biometric unlock no longer opens on this device (fingerprints
 *  changed, the record is damaged or came from another Mac). `vault_unlock_biometric` removes
 *  it.
 */
"biometric_stale" | "not_found" | "invalid_input" | "key_parse" | "ssh" | "sftp" | "sync" | "sync_auth" | "sync_offline" | "remote_initialized" | "remote_not_initialized" | 
/**  Another sync setup (flow A or C, §6.6) is still running. */
"sync_setup_busy" | 
/**  Sync is already set up on this device, so it cannot join a cloud vault (flow C). */
"sync_already_configured" | 
/**  In-app deployment (§6.7): Cloudflare rejected the API token. */
"cloudflare_token" | 
/**  The API token lacks the permission in `permission`. */
"cloudflare_permission" | 
/**  Any other Cloudflare API failure; `cf_code` has Cloudflare's code when it sent one. */
"cloudflare" | "subdomain_required" | "subdomain_unavailable" | "worker_name_taken" | 
/**  An upgrade found no Hatoba Worker with a vault under the name. */
"worker_not_found" | 
/**  An upgrade found a Worker newer than the one this build deploys. */
"worker_newer" | 
/**  This build does not embed the Worker, so it cannot deploy it. */
"no_worker_bundle" | 
/**
 *  AI assistant (§13): a model provider or search provider failed. `http_status` has the
 *  status it answered with, when it answered; `detail` is its own message.
 */
"ai" | 
/**  A downloaded update does not carry a valid signature from the release key (spec §11). */
"update_signature" | "cancelled" | "io" | "internal";

/**
 *  A forward that failed to start on its host's connection, until it starts or stops: a port in
 *  use, say.
 */
export type FailedForwardView = {
	forward_id: string,
	error: AppError,
};

export type FileEntry = {
	name: string,
	path: string,
	is_dir: boolean,
	is_symlink: boolean,
	size: number,
	modified: number | null,
	permissions: string,
};

export type ForwardInput = {
	id: string | null,
	host_id: string,
	/**  Trimmed; empty for none. */
	name: string,
	kind: ForwardKind,
	bind_address: string,
	bind_port: number,
	/**  Ignored for a dynamic forward. */
	dest_host: string,
	dest_port: number,
	auto_start: boolean,
};

/**  Which way a forward goes. */
export type ForwardKind = 
/**  `ssh -L`: listens on this computer, and the server connects to the destination. */
"local" | 
/**  `ssh -R`: listens on the server, and this computer connects to the destination. */
"remote" | 
/**  `ssh -D`: a SOCKS proxy on this computer, whose connections the server opens. */
"dynamic";

/**
 *  One-off credentials for the connection a forward's start opens (SSH-03): used once, never
 *  stored.
 */
export type ForwardOptions = {
	password: string | null,
	passphrase: string | null,
};

/**
 *  A saved forward. The bind address and port are on this computer, or on the server for a
 *  remote forward.
 */
export type ForwardView = {
	id: string,
	host_id: string,
	/**  Empty for a forward named by its rule. */
	name: string,
	kind: ForwardKind,
	bind_address: string,
	bind_port: number,
	/**
	 *  As the server reaches it, or as this computer does for a remote forward; empty and 0 for
	 *  a dynamic one.
	 */
	dest_host: string,
	dest_port: number,
	auto_start: boolean,
};

/**
 *  FWD-05: a host's connection ended on its own with forwards on it, which stopped with it.
 *  Closing it with nothing left on it, the lock (SEC-03) and quitting send nothing.
 */
export type ForwardsLostEvent = {
	host_id: string,
	host_name: string,
	error: AppError,
};

export type GenerateAlgorithm = "ed25519" | "rsa";

export type GroupInput = {
	id: string | null,
	name: string,
	parent_id: string | null,
	sort: number,
};

export type GroupView = {
	id: string,
	name: string,
	parent_id: string | null,
	sort: number,
	/**
	 *  The dashboard shows the group's hosts on this device (HOST-14). Device-local, and on
	 *  until turned off.
	 */
	dashboard: boolean,
};

/**  SSH-16: a saved host's open connection, which its terminal tabs and forwards share. */
export type HostConnectionView = {
	host_id: string,
	/**  The host's name when it connected. */
	host_name: string,
	/**  By port. */
	forwards: RunningForwardView[],
	failed: FailedForwardView[],
};

/**  One of a host's environment variables (SSH-14). */
export type HostEnvVar = {
	name: string,
	value: string,
};

export type HostInput = {
	id: string | null,
	name: string,
	address: string,
	port: number,
	username: string,
	auth_kind: AuthKind,
	/**  `None` keeps the saved password (HOST-08). */
	password: string | null,
	key_id: string | null,
	group_id: string | null,
	tags: string[],
	favorite: boolean,
	jump_host_id: string | null,
	proxy_mode: ProxyMode,
	/**  Required when `proxy_mode` is `proxy`, ignored otherwise. */
	proxy_id: string | null,
	note: string,
	/**  At most 16 KB of UTF-8 (AI-37). */
	ai_notes: string,
	/**  Names are trimmed; see `hatoba_core::model::check_host_env` for the rules (SSH-14). */
	env: HostEnvVar[],
};

export type HostKeyPrompt = {
	request_id: string,
	session_id: string | null,
	host: string,
	port: number,
	key_type: string,
	fingerprint: string,
	kind: HostKeyPromptKind,
	known_fingerprint: string | null,
	known_key_type: string | null,
};

export type HostKeyPromptKind = "new" | "changed";

export type HostView = {
	id: string,
	name: string,
	address: string,
	port: number,
	username: string,
	auth_kind: AuthKind,
	has_password: boolean,
	key_id: string | null,
	group_id: string | null,
	tags: string[],
	favorite: boolean,
	jump_host_id: string | null,
	/**  SSH-13. With a jump host, the jump host's choice applies instead. */
	proxy_mode: ProxyMode,
	/**  The saved proxy, when `proxy_mode` is `proxy`. */
	proxy_id: string | null,
	note: string,
	/**  What the AI assistant is told about the host (AI-37). */
	ai_notes: string,
	updated_at: number,
	last_connected_at: number | null,
	/**
	 *  The server's operating system from its SSH identification string on the last connection
	 *  from this device, such as `ubuntu` (HOST-11). Device-local, like `last_connected_at`.
	 */
	os: string | null,
	/**
	 *  The host's terminals show the server's resource usage on this device (TERM-12).
	 *  Device-local, like `last_connected_at`, and off until turned on.
	 */
	show_stats: boolean,
	/**
	 *  The dashboard shows the host on this device (HOST-14). Device-local, like
	 *  `last_connected_at`, and on until turned off.
	 */
	dashboard: boolean,
	/**  Environment variables the terminal asks the server to set (SSH-14). */
	env: HostEnvVar[],
};

/**  A host an import can create. */
export type ImportCandidate = {
	/**  Identifies it within the source, for `hosts_import`. */
	id: string,
	name: string,
	address: string,
	port: number,
	username: string,
	/**  The folder it is in, its names joined by ` / `. */
	folder: string | null,
	/**
	 *  The private key file an import with keys reads: the first one that exists, otherwise the
	 *  first one listed.
	 */
	identity_file: string | null,
	/**  Whether `identity_file` exists, so that importing keys would read it. */
	identity_file_found: boolean,
	/**
	 *  The client keeps the private key itself, so it is not imported; the key's name there, or
	 *  empty when the session does not name it.
	 */
	kept_key: string | null,
	/**  The jump host: a `ProxyJump` value, another session's name, or gateways. */
	jump: string | null,
	/**  The proxy it imports, such as `SOCKS5 127.0.0.1:1080`. */
	proxy: string | null,
	/**
	 *  A proxy setting that is not imported, such as `ProxyCommand …`: the host connects
	 *  without it.
	 */
	skipped_proxy: string | null,
	/**  A host with the same name exists. */
	exists: boolean,
};

export type ImportPreview = {
	/**
	 *  The file, folder or registry key the hosts were read from; `None` when nothing was found
	 *  where the client keeps its sessions.
	 */
	location: string | null,
	/**  The client encrypted the file, so nothing could be read from it. */
	encrypted: boolean,
	candidates: ImportCandidate[],
};

export type ImportResult = {
	hosts_created: number,
	keys_imported: number,
	warnings: string[],
};

/**  Where a host import reads from (SSH-11, SSH-12, SSH-15). */
export type ImportSource = "ssh_config" | "xshell" | "finalshell" | "mobaxterm" | "putty" | "securecrt" | "tabby";

export type ItemType = "host" | "group" | "key" | "known_host" | "forward" | "snippet" | "proxy" | "ai_provider" | "search_provider" | "ai_conversation" | "ai_message" | "skill" | "skill_file" | "mcp_server" | "ai_memory" | "settings";

